mapper.select:
SELECT COUNT(*)
FROM v_comment_visible c
WHERE c.novel_id = #{novelId}
  AND c.parent_id IS NULL

    AND c.chapter_id = #{chapterId}
    AND c.chapter_id IS NULL

SELECT c.comment_id, c.novel_id, c.chapter_id, c.parent_id, c.user_id, c.content, c.like_count, c.reply_count, c.status, c.audit_status, c.created_at, u.nickname, n.title AS novel_title FROM comment c JOIN app_user u ON u.user_id = c.user_id JOIN novel n ON n.novel_id = c.novel_id
AND c.novel_id = #{novelId} AND c.status = #{status} AND c.audit_status = #{auditStatus}
AND c.content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY c.created_at DESC, c.comment_id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM comment c

    AND c.novel_id = #{novelId}
    AND c.status = #{status}
    AND c.audit_status = #{auditStatus}

        AND c.content LIKE CONCAT('%', #{keyword}, '%')
